mapper.select:
select T.DM_CLCT_ID as clctId ,M.DM_ID as dataModelId ,M.DM_NM as dataModelNm ,M.DM_SYS_CD as dataModelSysCd ,(select SYS_NM from TB_SYS_INFO where sys_cd = M.DM_SYS_CD) as dataModelSysNm ,M.DM_DS_ID as dataModelDsId ,(select DSN from ndata.TB_DATA_SOURCE where ds_id = M.DM_DS_ID) as dataModelDsNm ,M.VER as dataModelVer ,to_char(to_timestamp(T.CLCT_START_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS') as clctStartDt ,to_char(to_timestamp(T.CLCT_END_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS') as clctEndDt ,T.CLCT_CMPTN_YN as clctCmptnYn from TB_DATA_MODEL_CLCT T, TB_DATA_MODEL M where T.DM_ID = M.DM_ID AND M.USE_YN = 'Y'
AND M.DM_ID = #{schId}
AND M.DM_NM ILIKE '%' || #{schNm} || '%'
AND M.DM_SYS_CD in (select SYS_CD from TB_SYS_INFO where SYS_NM ILIKE '%' || #{schSysNm} || '%')
AND T.CLCT_END_DT >= #{from}
AND T.CLCT_END_DT <= #{to}
order by T.CLCT_END_DT DESC NULLS LAST

select OBJ_NM as objNm ,OBJ_NM_KR as objNmKr ,OBJ_OWNER as objOwner ,OBJ_DESC as objDesc ,OBJ_COMMENT as objComment ,OBJ_ATTR_CNT as objAttrCnt ,USE_YN as useYn from TB_DATA_MODEL_OBJ where DM_ID = #{dataModelId}
AND USE_YN = 'Y'
order by OBJ_NM

SELECT DM_ID AS "dataModelId", DM_NM AS "dataModelNm", DM_DS_ID AS "dataModelDsId"
FROM TB_DATA_MODEL
WHERE DM_ID = #{dataModelId}

SELECT DM_CLCT_ID AS "clctId", CLCT_END_DT AS "clctEndDt"
FROM TB_DATA_MODEL_CLCT
WHERE DM_CLCT_ID = #{clctId}

select A.OBJ_NM ,(select OBJ_NM_KR from TB_DATA_MODEL_OBJ where DM_ID = A.DM_ID and OBJ_NM = A.OBJ_NM) as OBJ_NM_KR ,A.ATTR_NM ,A.ATTR_NM_KR ,A.ATTR_COMMENT ,A.DATA_TYPE ,A.DATA_LEN ,A.DATA_DECIMAL_LEN ,A.TERMS_STND_YN ,A.DOMAIN_STND_YN ,A.WORD_LST ,A.WORD_STND_LST ,A.NULLABLE_YN ,A.PK_YN ,A.FK_YN ,A.DEFAULT_VAL ,A.ATTR_ORD from TB_DATA_MODEL_ATTR A where A.DM_ID = #{schId}
AND (A.OBJ_NM ILIKE '%'||#{schObjNm}||'%' OR A.ATTR_NM ILIKE '%'||#{schAttrNm}||'%')
AND A.TERMS_STND_YN = #{schStndYn}
order by A.OBJ_NM, A.ATTR_ORD

select T.DM_CLCT_ID as clctId ,M.DM_ID as dataModelId ,M.DM_NM as dataModelNm ,M.DM_SYS_CD as dataModelSysCd ,(select SYS_NM from TB_SYS_INFO where sys_cd = M.DM_SYS_CD) as dataModelSysNm ,M.DM_DS_ID as dataModelDsId ,(select DSN from ndata.TB_DATA_SOURCE where ds_id = M.DM_DS_ID) as dataModelDsNm ,M.VER as dataModelVer ,to_char(to_timestamp(T.CLCT_START_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS') as clctStartDt ,to_char(to_timestamp(T.CLCT_END_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS') as clctEndDt ,T.CLCT_CMPTN_YN as clctCmptnYn ,(select count(*) from TB_DATA_MODEL_OBJ where DM_ID = M.DM_ID and USE_YN='Y') as objCnt ,(select count(*) from TB_DATA_MODEL_ATTR where DM_ID = M.DM_ID and USE_YN='Y') as attrCnt ,0 as stndRate ,0 as nonStndCnt ,0 as noTermsCnt ,0 as domainMismatchCnt from TB_DATA_MODEL_CLCT T JOIN TB_DATA_MODEL M on T.DM_ID = M.DM_ID where M.USE_YN = 'Y'
AND M.DM_NM ILIKE '%' || #{schNm} || '%'
AND M.DM_SYS_CD in (select SYS_CD from TB_SYS_INFO where SYS_NM ILIKE '%' || #{schSysNm} || '%')
AND T.CLCT_END_DT >= #{from}
AND T.CLCT_END_DT <= #{to}
order by T.CLCT_END_DT DESC NULLS LAST

mapper.insert:
INSERT INTO TB_DATA_MODEL
(
  DM_ID
 ,DM_NM
 ,DM_SYS_CD
 ,DM_DS_ID
 ,MODEL_TYPE
 ,VER
 ,CRET_DT
 ,CRET_USER_ID
)
VALUES
(
  #{dataModelId}
 ,#{dataModelNm}
 ,#{dataModelSysCd}
 ,#{dataModelDsId, jdbcType=VARCHAR}
 ,COALESCE(#{modelType, jdbcType=VARCHAR}, 'PHYSICAL')
 ,#{ver, jdbcType=VARCHAR}
 ,to_char(now(), 'YYYYMMDDHH24MISS')
 ,#{cretUserId, jdbcType=VARCHAR}
)

mapper.update:
UPDATE TB_DATA_MODEL
SET
  DM_NM = #{dataModelNm}
 ,DM_SYS_CD = #{dataModelSysCd}
 ,DM_DS_ID = #{dataModelDsId}
 ,VER = #{ver, jdbcType=VARCHAR}
 ,UPDT_DT = to_char(now(), 'YYYYMMDDHH24MISS')
 ,UPDT_USER_ID = #{updtUserId, jdbcType=VARCHAR}
where DM_ID = #{dataModelId}

mapper.insert:
           INSERT INTO TB_DATA_MODEL_CLCT
           (
             DM_CLCT_ID
            ,DM_ID
            ,CLCT_TYPE
			,CLCT_START_DT
			,CRET_USER_ID
           )
           VALUES
           (
             #{clctId}
            ,#{dataModelId}
            ,COALESCE(#{clctType, jdbcType=VARCHAR}, 'DBMS')
            ,to_char(now(), 'YYYYMMDDHH24MISS')
			,#{cretUserId, jdbcType=VARCHAR}
		   ) ON CONFLICT (DM_CLCT_ID,DM_ID) DO UPDATE
            SET
              CLCT_END_DT = #{clctEndDt, jdbcType=VARCHAR}
			 ,CLCT_CMPTN_YN = #{clctCmptnYn, jdbcType=VARCHAR}

           INSERT INTO TB_DATA_MODEL_ATTR
           (
             DM_ID
			,OBJ_OWNER
			,OBJ_NM
			,ATTR_NM
			,ATTR_NM_KR
			,ATTR_COMMENT
			,DATA_TYPE
			,DATA_LEN
			,DATA_DECIMAL_LEN
			,NULLABLE_YN
			,PK_YN
			,FK_YN
			,DEFAULT_VAL
			,ATTR_ORD
			,TERMS_STND_YN
			,DOMAIN_STND_YN
			,USE_YN
           )
           VALUES
           (
             #{dataModelId}
            ,#{objOwner, jdbcType=VARCHAR}
            ,#{objNm, jdbcType=VARCHAR}
            ,#{attrNm, jdbcType=VARCHAR}
			,#{attrNmKr, jdbcType=VARCHAR}
			,#{attrComment, jdbcType=VARCHAR}
			,#{dataType, jdbcType=VARCHAR}
			,#{dataLen, jdbcType=BIGINT}
			,#{dataDecimalLen, jdbcType=SMALLINT}
			,#{nullableYn, jdbcType=VARCHAR}
			,#{pkYn, jdbcType=VARCHAR}
			,#{fkYn, jdbcType=VARCHAR}
			,#{defaultVal, jdbcType=VARCHAR}
			,#{attrOrder, jdbcType=SMALLINT}
			,COALESCE(#{termsStndYn, jdbcType=VARCHAR}, 'N')
			,COALESCE(#{domainStndYn, jdbcType=VARCHAR}, 'N')
			,'Y'
		   )
		   ON CONFLICT (DM_ID, OBJ_NM, ATTR_NM) DO UPDATE SET
			ATTR_COMMENT = EXCLUDED.ATTR_COMMENT,
			OBJ_OWNER = EXCLUDED.OBJ_OWNER,
			DATA_TYPE = EXCLUDED.DATA_TYPE,
			DATA_LEN = EXCLUDED.DATA_LEN,
			DATA_DECIMAL_LEN = EXCLUDED.DATA_DECIMAL_LEN,
			NULLABLE_YN = EXCLUDED.NULLABLE_YN,
			PK_YN = EXCLUDED.PK_YN,
			FK_YN = EXCLUDED.FK_YN,
			DEFAULT_VAL = EXCLUDED.DEFAULT_VAL,
			ATTR_ORD = EXCLUDED.ATTR_ORD,
			USE_YN = 'Y',
			DELETED_DT = NULL

           INSERT INTO TB_DATA_MODEL_OBJ
           (
             DM_ID
			,OBJ_NM
			,OBJ_NM_KR
			,OBJ_OWNER
			,OBJ_DESC
			,OBJ_COMMENT
			,OBJ_ATTR_CNT
			,USE_YN
           )
           VALUES
           (
             #{dataModelId}
            ,#{objNm, jdbcType=VARCHAR}
			,#{objNmKr, jdbcType=VARCHAR}
			,#{objOwner, jdbcType=VARCHAR}
			,#{objDesc, jdbcType=VARCHAR}
			,#{objComment, jdbcType=VARCHAR}
			,#{objAttrCnt, jdbcType=SMALLINT}
			,'Y'
		   )
		   ON CONFLICT (DM_ID, OBJ_NM) DO UPDATE SET
			OBJ_COMMENT = EXCLUDED.OBJ_COMMENT,
			OBJ_OWNER = EXCLUDED.OBJ_OWNER,
			OBJ_ATTR_CNT = EXCLUDED.OBJ_ATTR_CNT,
			USE_YN = 'Y',
			DELETED_DT = NULL

mapper.update:
UPDATE TB_DATA_MODEL_OBJ SET USE_YN = 'N', DELETED_DT = #{deletedDt}
WHERE DM_ID = #{dataModelId} AND USE_YN = 'Y'
AND OBJ_NM NOT IN
#{nm}

UPDATE TB_DATA_MODEL_ATTR SET USE_YN = 'N', DELETED_DT = #{deletedDt}
WHERE DM_ID = #{dataModelId} AND USE_YN = 'Y'
AND (OBJ_NM || '.' || ATTR_NM) NOT IN
#{nm}

mapper.insert:
INSERT INTO TB_DATA_MODEL_SCHEMA
(
	 DM_ID
	,SCHEMA_NM
	,USE_YN
	,CRET_DT
	,CRET_USER_ID
)
VALUES
(
	 #{dataModelId}
	,#{schemaNm}
	,#{useYn}
	,to_char(now(), 'YYYYMMDDHH24MISS')
	,#{cretUserId, jdbcType=VARCHAR}
)
ON CONFLICT (DM_ID, SCHEMA_NM) DO UPDATE
SET USE_YN = #{useYn}

mapper.update:
UPDATE TB_DATA_MODEL_INDEX SET USE_YN = 'N', DELETED_DT = #{deletedDt}
WHERE DM_ID = #{dataModelId} AND USE_YN = 'Y'
AND (COALESCE(OBJ_OWNER,'') || '|' || TABLE_NM || '|' || INDEX_NM || '|' || COLUMN_POS) NOT IN
#{k}

UPDATE TB_DATA_MODEL_CONSTRAINT SET USE_YN = 'N', DELETED_DT = #{deletedDt}
WHERE DM_ID = #{dataModelId} AND USE_YN = 'Y'
AND (COALESCE(OBJ_OWNER,'') || '|' || TABLE_NM || '|' || CONSTRAINT_NM || '|' || COLUMN_POS) NOT IN
#{k}

UPDATE TB_DATA_MODEL_OBJ SET
	 OBJ_NM_KR = #{objNmKr, jdbcType=VARCHAR}
	,OBJ_OWNER = #{objOwner, jdbcType=VARCHAR}
	,OBJ_DESC  = #{objDesc, jdbcType=VARCHAR}
WHERE DM_ID = #{dataModelId} AND OBJ_NM = #{objNm}

UPDATE TB_DATA_MODEL_ATTR SET
	 ATTR_NM_KR       = #{attrNmKr, jdbcType=VARCHAR}
	,DATA_TYPE        = #{dataType, jdbcType=VARCHAR}
	,DATA_LEN         = #{dataLen, jdbcType=BIGINT}
	,DATA_DECIMAL_LEN = #{dataDecimalLen, jdbcType=SMALLINT}
	,NULLABLE_YN      = #{nullableYn, jdbcType=VARCHAR}
	,PK_YN            = #{pkYn, jdbcType=VARCHAR}
	,FK_YN            = #{fkYn, jdbcType=VARCHAR}
	,DEFAULT_VAL      = #{defaultVal, jdbcType=VARCHAR}
	,TERMS_STND_YN    = #{termsStndYn, jdbcType=VARCHAR}
	,DOMAIN_STND_YN   = #{domainStndYn, jdbcType=VARCHAR}
	,WORD_LST         = #{wordLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
	,WORD_STND_LST    = #{wordStndLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
WHERE DM_ID = #{dataModelId} AND OBJ_NM = #{objNm} AND ATTR_NM = #{attrNm}

UPDATE TB_DATA_MODEL_ATTR SET
	 ATTR_NM          = #{attrNm, jdbcType=VARCHAR}
	,ATTR_NM_KR       = #{attrNmKr, jdbcType=VARCHAR}
	,DATA_TYPE        = #{dataType, jdbcType=VARCHAR}
	,DATA_LEN         = #{dataLen, jdbcType=BIGINT}
	,DATA_DECIMAL_LEN = #{dataDecimalLen, jdbcType=SMALLINT}
	,TERMS_STND_YN    = #{termsStndYn, jdbcType=VARCHAR}
	,DOMAIN_STND_YN   = #{domainStndYn, jdbcType=VARCHAR}
	,WORD_LST         = #{wordLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
	,WORD_STND_LST    = #{wordStndLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
WHERE DM_ID = #{dataModelId} AND OBJ_NM = #{objNm} AND ATTR_NM = #{origAttrNm}

UPDATE TB_DATA_MODEL_OBJ O SET OBJ_ATTR_CNT = (
	SELECT COUNT(*) FROM TB_DATA_MODEL_ATTR A
	WHERE A.DM_ID = O.DM_ID AND A.OBJ_NM = O.OBJ_NM
)
WHERE O.DM_ID = #{dataModelId} AND O.OBJ_NM = #{objNm}
